package earth.terrarium.pastel.data.lang.guidebook.main;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class GeodesEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.geodes.name", "Geodes");
		provider.add("book.pastel.guidebook.geodes.page0.text", "I was told about a strange occurrence underground, but this picture is the only clue I have at the moment.");
		provider.add("book.pastel.guidebook.geodes.page0.title", "Gemstone Geodes");
		provider.add("book.pastel.guidebook.geodes.page1.text", "Breaking Clusters gives me Gemstone Shards, which seem to inherit most of the original properties.\\\nEach type of gem seems to represent a different type of fundamental property.\\\n\\\nLooks like different heights encourage the formation of certain types. To find them all, it will make sense to search in different places.");
		provider.add("book.pastel.guidebook.geodes.page2.text", "The precious gems are protected by layers of [#](bb00bb)Calcite[#]() and [#](bb00bb)Basalt[#]().");
		provider.add("book.pastel.guidebook.geodes.page3.text", "Now that I'm paying attention, I notice small inclusions of gems in the rock all over the place.\\\nIf I see such an ore a geode is surely not far!\\\n\\\nWhile not renewable like Gemstone Clusters, Gemstone Ore yields a lot of shards and some powder, especially if broken with a Fortune tool.");
		provider.add("book.pastel.guidebook.geodes.page3.title", "Gemstone Ores");
		provider.add("book.pastel.guidebook.geodes.page4.text", "Topaz geodes are gigantic compared to others - fitting considering their element of **[#](5bffed)MATTER.[#]()**. They are found exclusively high up in mountains and massive hills.");
		provider.add("book.pastel.guidebook.geodes.page4.title", "Topaz Geodes");
		provider.add("book.pastel.guidebook.geodes.page5.text", "As elements of **[#](ff4ff6)TIME[#]()**, Amethyst Geodes tend to maintain their existence in the deepest layers of the world, quietly sealed off from all the other happenings.\\\nLeisurely yet imposing.");
		provider.add("book.pastel.guidebook.geodes.page5.title", "Amethyst Geodes");
		provider.add("book.pastel.guidebook.geodes.page6.text", "Citrine Geodes are found in the middle layers of the world, sometimes even accessible from the surface. These geodes are small, but harbor tremendous **[#](eded00)ENERGY[#]()**. No wonder I found them to be particularly prone to having cracks.");
		provider.add("book.pastel.guidebook.geodes.page6.title", "Citrine Geodes");
		provider.add("book.pastel.guidebook.geodes.page7.text", "In the deep I stumbled upon Moonstone Geodes! I always suspected that this variant *must* exist in some form.\\\n\\\nThese majestic geodes shine in the brightest of whites. Almost blinding, when accustomed to the darkness of Imbrifer.");
		provider.add("book.pastel.guidebook.geodes.page7.title", "Moonstone Geodes");
	}
}
